    /// THE ANIMATION'S DRAW-TIME REMAP — the base frame-0 tile the
     /// mesher bakes (the strip's own palette row or appended frame-00)
     /// the current animation frame's tile the tick answers: the
     /// playlist position `(tick / frametime) % len` the vanilla
     /// TextureAtlasSprite animator's per-tick walk speaks, the strips'
     /// base tiles their own strips keep, every other tile the
     /// identity wears (the destroy stages, the farmland's wet face,
     /// the whole block palette).
     pub fn anim_tile(base: u16, tick: u64) -> u16 {
         match base {
        FIRE_0_FRAME0 => {
             let pos = ((tick / FIRE_0_FRAMETIME) % FIRE_0_PLAYLIST.len() as u64) as usize;
             FIRE_0_FRAMES[FIRE_0_PLAYLIST[pos] as usize]
         }
        FIRE_1_FRAME0 => {
             let pos = ((tick / FIRE_1_FRAMETIME) % FIRE_1_PLAYLIST.len() as u64) as usize;
             FIRE_1_FRAMES[FIRE_1_PLAYLIST[pos] as usize]
         }
        SOUL_FIRE_0_FRAME0 => {
             let pos = ((tick / SOUL_FIRE_0_FRAMETIME) % SOUL_FIRE_0_PLAYLIST.len() as u64) as usize;
             SOUL_FIRE_0_FRAMES[SOUL_FIRE_0_PLAYLIST[pos] as usize]
         }
        SOUL_FIRE_1_FRAME0 => {
             let pos = ((tick / SOUL_FIRE_1_FRAMETIME) % SOUL_FIRE_1_PLAYLIST.len() as u64) as usize;
             SOUL_FIRE_1_FRAMES[SOUL_FIRE_1_PLAYLIST[pos] as usize]
         }
        WATER_FRAME0 => {
             let pos = ((tick / WATER_FRAMETIME) % WATER_PLAYLIST.len() as u64) as usize;
             WATER_FRAMES[WATER_PLAYLIST[pos] as usize]
         }
        LAVA_FRAME0 => {
             let pos = ((tick / LAVA_FRAMETIME) % LAVA_PLAYLIST.len() as u64) as usize;
             LAVA_FRAMES[LAVA_PLAYLIST[pos] as usize]
         }
        CAMPFIRE_FIRE_FRAME0 => {
             let pos = ((tick / CAMPFIRE_FIRE_FRAMETIME) % CAMPFIRE_FIRE_PLAYLIST.len() as u64) as usize;
             CAMPFIRE_FIRE_FRAMES[CAMPFIRE_FIRE_PLAYLIST[pos] as usize]
         }
        SOUL_CAMPFIRE_FIRE_FRAME0 => {
             let pos = ((tick / SOUL_CAMPFIRE_FIRE_FRAMETIME) % SOUL_CAMPFIRE_FIRE_PLAYLIST.len() as u64) as usize;
             SOUL_CAMPFIRE_FIRE_FRAMES[SOUL_CAMPFIRE_FIRE_PLAYLIST[pos] as usize]
         }
        CAMPFIRE_LOG_LIT_FRAME0 => {
             let pos = ((tick / CAMPFIRE_LOG_LIT_FRAMETIME) % CAMPFIRE_LOG_LIT_PLAYLIST.len() as u64) as usize;
             CAMPFIRE_LOG_LIT_FRAMES[CAMPFIRE_LOG_LIT_PLAYLIST[pos] as usize]
         }
        SOUL_CAMPFIRE_LOG_LIT_FRAME0 => {
             let pos = ((tick / SOUL_CAMPFIRE_LOG_LIT_FRAMETIME) % SOUL_CAMPFIRE_LOG_LIT_PLAYLIST.len() as u64) as usize;
             SOUL_CAMPFIRE_LOG_LIT_FRAMES[SOUL_CAMPFIRE_LOG_LIT_PLAYLIST[pos] as usize]
         }
        WATER_FLOW_FRAME0 => {
             let pos = ((tick / WATER_FLOW_FRAMETIME) % WATER_FLOW_PLAYLIST.len() as u64) as usize;
             WATER_FLOW_FRAMES[WATER_FLOW_PLAYLIST[pos] as usize]
         }
        LAVA_FLOW_FRAME0 => {
             let pos = ((tick / LAVA_FLOW_FRAMETIME) % LAVA_FLOW_PLAYLIST.len() as u64) as usize;
             LAVA_FLOW_FRAMES[LAVA_FLOW_PLAYLIST[pos] as usize]
         }
        NETHER_PORTAL_FRAME0 => {
             let pos = ((tick / NETHER_PORTAL_FRAMETIME) % NETHER_PORTAL_PLAYLIST.len() as u64) as usize;
             NETHER_PORTAL_FRAMES[NETHER_PORTAL_PLAYLIST[pos] as usize]
         }
        _ => base,
     }
}
